// Settings + all projects come from data/projects.json (generated by scripts/build.py)
let DATA = { site: {}, projects: [] };
const app = document.getElementById('app');
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const slugify = s => s.toLowerCase().replace(/[^a-z0-9]+/g, '-');
const setMenu = open => {
  document.body.classList.toggle('menu-open', open);
  document.getElementById('burger').setAttribute('aria-expanded', open);
};

async function init() {
  try {
    DATA = await (await fetch('data/projects.json', { cache: 'no-cache' })).json();
  } catch (e) {
    app.innerHTML = '<p class="empty">Could not load data/projects.json (use GitHub Pages or the preview from VS Code).</p>';
    return;
  }
  const s = DATA.site;
  document.title = s.name || 'Portfolio';
  document.getElementById('logo').innerHTML = s.logo
    ? `<img src="${esc(s.logo)}" alt="${esc(s.name)}">`
    : `<span class="logo-wrap"><span class="logo-name">${esc(s.name)}</span>${s.tagline ? `<span class="logo-tag">${esc(s.tagline)}</span>` : ''}</span>`;
  document.getElementById('copy').textContent = s.footer || '';
  document.getElementById('burger').addEventListener('click', () => setMenu(true));
  document.getElementById('close').addEventListener('click', () => setMenu(false));
  document.addEventListener('keydown', e => { if (e.key === 'Escape') setMenu(false); });
  document.getElementById('top').addEventListener('click', e => { e.preventDefault(); scrollTo({ top: 0, behavior: 'smooth' }); });
  window.addEventListener('hashchange', route);
  route();
}

function renderNav(active) {
  const items = [{ label: 'Overview', href: '#/', key: '' }]
    .concat((DATA.site.categories || []).map(c => ({ label: c, href: '#/category/' + slugify(c), key: slugify(c) })))
    .concat([{ label: 'Contact', href: '#/contact', key: 'contact' }]);
  document.getElementById('nav').innerHTML = items
    .map(i => `<a href="${i.href}" class="${i.key === active ? 'active' : ''}">${esc(i.label)}</a>`).join('');
}

function grid(list) {
  if (!list.length) return '<p class="empty">Nothing here yet.</p>';
  return '<div class="grid">' + list.map(p => `
    <a class="card" href="#/project/${esc(p.slug)}">
      <img loading="lazy" src="${esc(p.cover || '')}" alt="${esc(p.title)}">
      <div class="over"><h3>${esc(p.title)}</h3>${p.year ? `<span class="yr">${esc(p.year)}</span>` : ''}</div>
    </a>`).join('') + '</div>';
}

function related(p) {
  const others = DATA.projects.filter(x => x.slug !== p.slug);
  const same = others.filter(x => x.category === p.category);
  const rest = others.filter(x => x.category !== p.category);
  const pick = same.concat(rest).slice(0, 4);
  return pick.length ? `<section class="related"><h2>You may also like</h2>${grid(pick)}</section>` : '';
}

function project(slug) {
  const p = DATA.projects.find(x => x.slug === slug);
  if (!p) return '<p class="empty">Project not found.</p>';
  const media = (p.images || []).map(m => {
    if (typeof m === 'object' && m.video) return `<div class="video"><iframe src="${esc(m.video)}" allow="fullscreen; picture-in-picture" allowfullscreen loading="lazy"></iframe></div>`;
    return `<img loading="lazy" src="${esc(typeof m === 'object' ? m.src : m)}" alt="${esc(p.title)}">`;
  }).join('');
  return `<article class="project">
    <h1>${esc(p.title)}</h1>
    ${p.description ? `<p class="desc">${esc(p.description)}</p>` : ''}
    <div class="media">${media}</div>
    ${related(p)}
  </article>`;
}

function contact() {
  const c = DATA.site.contact || {};
  return `<section class="contact"><p>${esc(c.text || '')}</p>
    ${c.email ? `<p><a href="mailto:${esc(c.email)}">${esc(c.email)}</a></p>` : ''}
    ${(c.links || []).map(l => `<p><a href="${esc(l.url)}" target="_blank" rel="noopener">${esc(l.label)}</a></p>`).join('')}</section>`;
}

function route() {
  const [, kind, arg] = location.hash.split('/');
  setMenu(false);
  scrollTo(0, 0);
  if (kind === 'category') {
    renderNav(arg);
    app.innerHTML = grid(DATA.projects.filter(p => slugify(p.category || '') === arg));
  } else if (kind === 'project') {
    const p = DATA.projects.find(x => x.slug === arg);
    renderNav(p ? slugify(p.category || '') : '');
    app.innerHTML = project(arg);
  } else if (kind === 'contact') {
    renderNav('contact'); app.innerHTML = contact();
  } else {
    renderNav(''); app.innerHTML = grid(DATA.projects);
  }
}
init();
